-- private

function GachaponResultNew:DoShowInfo_()
    CfUtils.SetActive(self.BtnSkip, false)
    CfUtils.SetActive(self.BtnShare, false)
    CfUtils.SetActive(self.screenBtn, false)
    CfUtils.SetActive(self.frontBlock, false)
    CfUtils.SetActive(self.ScreenBlock, false)
    CfUtils.SetActive(self.BottomTips, false)
    CfUtils.SetActive(self.SsrLight, self._isShowSsrLight)

    local result = checkTable(self._gachaponData)
    local cardId = checkInt(result.goodsId)
    local isNew  = isSet(result, "playerCard")
    local level  = isNew and result.playerCard.cardLevel or 1
    self:updateCardInfo_(cardId, isNew, level)
end


---@param cardId integer
---@param isNew boolean
---@param level integer
function GachaponResultNew:updateCardInfo_(cardId, isNew, level)
    CfUtils.SetActive(self.ImgNew, checkBool(isNew))

    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    
    -- 卡牌品质
    local cardRare = checkInt(cardVo.rare)
    CfUtils.SetUISwitchText(self.TxtCat, cardRare)
    CfUtils.SetUISwitchText(self.CardName, cardRare)
    CfUtils.SetUISwitchImage(self.ImgRareIcon, cardRare)
    CfUtils.SetUISwitchImage(self.ImgRareIcon2, cardRare)
    CfUtils.SetUISwitchImage(self.ImgRareIconbg, cardRare)
    CfUtils.SetUISwitchImage(self.ImgFloorLine, cardRare)
    CfUtils.SetUISwitchParticleSystem(self.RareParticle1, cardRare)
    CfUtils.SetUISwitchParticleSystem(self.RareParticle2, cardRare)
    CfUtils.SetUISwitchParticleSystem(self.RareParticle3, cardRare)
    
    -- 卡牌名称/角色名
    local roleVo = cardConfMgr:GetRolesVo(cardVo.characterId) or {}
    CfUtils.FillText(self.RoleEngName, tostring(roleVo.englishName))
    CfUtils.FillText(self.RoleName, tostring(roleVo.name))

    local cardLevel = checkInt(level)
    local cardName  = tostring(cardVo.name)
    if cardLevel > 1 then
        CfUtils.FillText(self.CardName, localize('Lv._num_ _roleName_·_cardName_', {_num_ = cardLevel, _roleName_ = tostring(roleVo.name), _cardName_ = cardName}))
    else
        CfUtils.FillText(self.CardName, localize('_roleName_·_cardName_', {_num_ = cardLevel, _roleName_ = tostring(roleVo.name), _cardName_ = cardName}))
    end

    -- 卡牌属性
    local cardAttr = checkInt(cardVo.attributeType)
    CfUtils.SetUISwitchImage(self.ElementImg, cardAttr)
    CfUtils.FillText(self.ElementTxt, cardConfMgr:GetRoleAttributeColorVo(cardAttr).name)

    -- 卡牌职业
    local cardCareer = checkInt(cardVo.career)
    CfUtils.SetUISwitchImage(self.CareerImg, cardCareer)
    CfUtils.FillText(self.CareerTxt, cardConfMgr:GetCardCareerRowByType(cardCareer).name)

    -- 卡牌阵营
    local cardRace = checkInt(cardVo.race)
    CfUtils.FillImage(self.RaceTypeImg, CardUtils.GetCardRaceIconPath(cardRace))
    CfUtils.FillText(self.RaceTypeTxt, cardConfMgr:GetRoleRaceVoById(cardRace).name)
    
    -- 角色声优
    CfUtils.FillText(self.TxtCVName, localize('CV: _name_', {_name_ = cardVo.cv}))

    -- 播放当前卡牌的台词
    ---@type RoleVoiceVo
    local roleVoiceVo = roleVoiceMgr:PlayDrawCardVoiceByCardId(cardId, nil, cardVo.defaultSkin)
    if roleVoiceVo then
        CfUtils.FillText(self.TxtCVContent, roleVoiceVo:GetDesk())
    else
        local errorTips = string.format("卡牌<%s>未在【角色表/角色台词表】找到对应数据", tostring(cardId))
        if Config.DEBUG then
            CfUtils.FillText(self.TxtCVContent, string.format("<color=#FF66FF>%s</color>", errorTips))
        else
            printError(errorTips)
        end
    end
end


