function GachaponResultNew:OnShareEnableCallback_()
    Events.Broadcast(Constants.EventNames.SHARE_BUTTON_REFRESH)
    CfUtils.SetActive(self.BottomTips, true)
end


function GachaponResultNew:OnCloseEnableCallback_()
    CfUtils.SetActive(self.BottomTips, true)
end


function GachaponResultNew:OnClickSkipButtonHandler_()
    if self._isPop ~= nil and self._isPop then
        return
    end

    self._isPop = true

    if self._closeCallback ~= nil then
        self._closeCallback()
    end

    self.controller:Close()
end


return GachaponResultNew
